import{COLORS,band,plan,flowValues,groundedExplanation}from'./planning.mjs';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={data:null,api:false,day:'weekday',hour:18,trips:6,filter:'all',search:'',incidents:[],selected:null,map:null,layer:null};
const title=s=>String(s).toLowerCase().replace(/\b\w/g,c=>c.toUpperCase()),label=s=>s.replaceAll('_',' '),color=b=>COLORS[b]||COLORS.unknown;
function toast(message){$('toast').textContent=message;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4500)}
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error((await r.json().catch(()=>({}))).error||'Request failed');return r.json()}
function summary(route,trips=state.trips){return plan(flowValues(route,state.day,state.hour),trips)}
function badge(b){return`<span class="badge" style="color:${color(b)};background:${color(b)}12">${b==='very_crowded'?'▲ ':b==='crowded'?'▲ ':b==='medium'?'◆ ':'● '}${esc(title(label(b)))}</span>`}
function geometrySvg(route,large=false){let coords=route.geometry?.coordinates;let schematic=!coords?.length;if(schematic)coords=route.sections.map((s,i)=>[i,Math.sin(i*.23)*.3]);const xs=coords.map(c=>c[0]),ys=coords.map(c=>c[1]);const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),w=large?640:360,h=large?300:145;const sx=(w-45)/Math.max(maxX-minX,.0001),sy=(h-40)/Math.max(maxY-minY,.0001),scale=Math.min(sx,sy),ox=(w-(maxX-minX)*scale)/2,oy=(h-(maxY-minY)*scale)/2;const point=p=>[ox+(p[0]-minX)*scale,h-oy-(p[1]-minY)*scale],path=cs=>cs.map((p,i)=>`${i?'L':'M'}${point(p)[0].toFixed(1)},${point(p)[1].toFixed(1)}`).join(' ');const values=flowValues(route,state.day,state.hour);let lines='';for(let i=0;i<route.sections.length;i++){const s=route.sections[i],cs=schematic?[coords[i],coords[Math.min(i+1,coords.length-1)]]:s.geometry?.coordinates;if(cs?.length){const b=state.trips?band(values[i]/state.trips):'no_service';lines+=`<path d="${path(cs)}" fill="none" stroke="${color(b)}" stroke-width="5" stroke-linecap="round"><title>${esc(s.from_name)} → ${esc(s.to_name)} · planning estimate</title></path>`}}
return`<svg class="map-fallback" viewBox="0 0 ${w} ${h}" role="img" aria-label="${schematic?'Stage schematic':'Supplied route geometry'} for ${esc(route.route_code)}"><defs><pattern id="grid-${route.id.slice(0,8)}" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#222a29" stroke-width=".35"/></pattern></defs><rect width="100%" height="100%" fill="url(#grid-${route.id.slice(0,8)})"/><path d="${path(coords)}" fill="none" stroke="#59636a" stroke-width="5" stroke-linecap="round"/>${lines}${[coords[0],coords.at(-1)].map(p=>`<circle cx="${point(p)[0]}" cy="${point(p)[1]}" r="3" fill="#f6eedf" stroke="#161817" stroke-width="1.5"/>`).join('')}</svg><span class="map-caption">${schematic?'STAGE SCHEMATIC · NOT A GEOGRAPHIC MAP':'SUPPLIED MTC ROUTE · COLORED SECTIONS ARE ESTIMATES'}</span>`}
function stageStrip(route){const values=flowValues(route,state.day,state.hour);return`<div class="stage-strip" role="img" aria-label="Planning load across stages, schematic">${route.sections.map((s,i)=>`<i style="background:${color(state.trips?band(values[i]/state.trips):'no_service')}" title="${esc(s.from_name)} → ${esc(s.to_name)}"></i>`).join('')}</div><div class="strip-caption">LOAD BY STAGE · SCHEMATIC, NOT GEOGRAPHIC</div>`}
function card(route){const p=summary(route),mapped=route.sections.filter(s=>s.geometry).length;return`<article class="route-card"><div class="card-header"><div><h3><span class="route-code">${esc(route.route_code)}</span> ${esc(title(route.origin))} – ${esc(title(route.terminus))}</h3><small>${esc(route.direction)} direction · ${route.sections.length} stage intervals</small></div>${badge(p.band)}</div><div class="route-mini">${geometrySvg(route)}</div>${stageStrip(route)}<div class="card-evidence">${Math.round(route.missing_destination_share*100)}% destinations estimated · ${mapped}/${route.sections.length} intervals matched to map</div><div class="card-footer"><span><strong>${p.load===null?'—':p.load.toFixed(0)}</strong> <small>peak avg. load proxy / bus</small></span><button class="text-button" data-route="${route.id}">View details →</button></div></article>`}
function visibleRoutes(){return state.data.routes.filter(r=>(state.filter==='all'||r.route_code===state.filter)&&`${r.route_code} ${r.origin} ${r.terminus} ${r.direction}`.toLowerCase().includes(state.search.toLowerCase()))}
function render(){const routes=visibleRoutes();$('routeGrid').innerHTML=routes.length?routes.map(card).join(''):'<div class="empty">No route matches your search.</div>';$('routeCount').textContent=routes.length;const all=state.data.routes.map(r=>summary(r));$('highCount').textContent=all.filter(p=>['crowded','very_crowded'].includes(p.band)).length;$('mediumCount').textContent=all.filter(p=>p.band==='medium').length;$('mappedCount').textContent=`${state.data.geography.geographic_section_matches}/${state.data.routes.reduce((n,r)=>n+r.sections.length,0)}`;$('assumptionText').textContent=`Colors use your assumption of ${state.trips} full-route trips/hour. They estimate load from reconstructed, boarding-hour section flow; actual service and crossing times are not observed.`;renderRecommendations();renderIncidents()}
function renderRecommendations(){const rows=state.data.routes.map(r=>({r,p:summary(r)})).sort((a,b)=>b.p.extra-a.p.extra);$('recommendations').innerHTML=rows.filter(x=>x.p.extra>0).map(({r,p},i)=>{const donor=rows.filter(x=>x.r.route_code!==r.route_code&&x.p.spare>0).sort((a,b)=>b.p.spare-a.p.spare)[0];return`<article class="recommendation"><span class="rec-number">${String(i+1).padStart(2,'0')}</span><div class="rec-copy"><h3>${esc(r.route_code)} · ${esc(title(r.origin))} – ${esc(title(r.terminus))}</h3><p>Explore ${p.extra} additional trip passage${p.extra===1?'':'s'} / hour to reach the target of 40 passengers per bus.</p><small>${donor?`${esc(donor.r.route_code)} ${esc(donor.r.direction)} has up to ${donor.p.spare} spare trip passages under the same assumptions. Transfer travel time and crew feasibility are unverified.`:'No donor route meets the target and minimum-service reserve under this assumption.'}</small></div><button class="primary" data-route="${r.id}">Explore scenario ↗</button></article>`}).join('')||'<div class="empty">No added trips are indicated at this hour under your service assumption. Check the data limitations before acting.</div>'}
async function loadIncidents(){if(state.api){try{state.incidents=(await api('/api/incidents')).incidents}catch{toast('Could not refresh field reports.')}}else{try{state.incidents=JSON.parse(localStorage.getItem('marina-incidents')||'[]')}catch{state.incidents=[]}}renderIncidents()}
function renderIncidents(){const open=state.incidents.filter(i=>i.status!=='resolved');$('incidentCount').textContent=open.length;$('fieldCount').textContent=state.incidents.length;$('reportStorage').textContent=state.api?'Shared through the local server':'Stored only in this browser';$('incidentList').innerHTML=state.incidents.length?state.incidents.map(i=>{const r=state.data.routes.find(r=>r.id===i.route_id);return`<article class="incident"><span class="badge" style="color:${i.status==='resolved'?COLORS.free:COLORS.medium}">${esc(i.status)}</span><div class="incident-copy"><b>${esc(r?.route_code||'Route')} · ${esc(title(i.type.replaceAll('_',' ')))}</b><p>${esc(i.description)}</p><small>${esc(new Date(i.created_at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))} · Field report, not a verified model observation</small></div>${i.status!=='resolved'?`<button data-status="${i.status==='reported'?'acknowledged':'resolved'}" data-id="${esc(i.id)}">${i.status==='reported'?'Acknowledge':'Resolve'}</button>`:''}</article>`}).join(''):'<div class="empty">No field reports yet. Drivers can report a delay, breakdown or unusual crowding from the mobile view.</div>'}
function chart(route){const vals=Array.from({length:24},(_,h)=>Math.max(...flowValues(route,state.day,h))/(state.trips||1)),max=Math.max(...vals,1);return`<svg class="chart" viewBox="0 0 600 120" role="img" aria-label="24-hour planning load profile">${vals.map((v,h)=>`<rect x="${h*25+2}" y="${95-v/max*80}" width="18" height="${Math.max(1,v/max*80)}" rx="2" class="${h===state.hour?'current':''}"><title>${h}:00 · ${v.toFixed(1)} estimated average-load proxy</title></rect>${h%3===0?`<text x="${h*25+1}" y="115">${String(h).padStart(2,'0')}</text>`:''}`).join('')}</svg>`}
function openRoute(id){const route=state.data.routes.find(r=>r.id===id);if(!route)return;state.selected=id;if(state.map){state.map.remove();state.map=null}const p=summary(route),values=flowValues(route,state.day,state.hour);$('routeDetail').innerHTML=`<button class="close" data-close="routeDialog" aria-label="Close route">×</button><div class="detail-header"><div class="eyebrow">ROUTE DETAIL / ${esc(route.direction)} / ${state.day.toUpperCase()} / ${state.hour}:00</div><h2 style="margin-top:10px">${esc(route.route_code)} · ${esc(title(route.origin))} – ${esc(title(route.terminus))}</h2><p>Historical ticket-derived flow · data through 31 March 2026 · service is your planning assumption</p></div><div class="detail-body"><div class="detail-grid"><div><div class="subheading">ROUTE &amp; SECTION EVIDENCE</div><div id="detailMap" class="detail-map">${geometrySvg(route,true)}</div><div class="detail-note">Colored road sections have name/proximity matches that need review. Unmatched roads remain grey. The list below includes the full estimated stage sequence.</div><div class="stage-list">${route.sections.map((s,i)=>{const b=state.trips?band(values[i]/state.trips):'no_service';return`<button class="stage-row" data-section="${i}"><i style="background:${color(b)}"></i><span>${esc(title(s.from_name))} → ${esc(title(s.to_name))}<small class="muted">${s.geometry?' · map match':' · schematic only'}</small></span><b style="color:${color(b)}">${state.trips?(values[i]/state.trips).toFixed(0):'—'}</b></button>`}).join('')}</div>${chart(route)}</div><div><section class="planning-box"><div class="subheading">WHAT IF WE CHANGE THE SERVICE?</div><h3>Explore an intervention</h3><p>Hold estimated demand fixed and compare trip passages. Adding one trip is not automatically adding one vehicle.</p><div class="scenario-inputs"><label>ADDITIONAL TRIPS / HOUR<input id="extraTrips" type="number" min="0" max="100" step="1" value="1"></label><label>TARGET LOAD / BUS<input id="targetLoad" type="number" min="1" max="150" step="1" value="40"></label></div><div id="scenarioResult"></div><button id="simulateButton" class="primary wide" style="margin-top:16px">Compare service plans →</button><p class="detail-note">No vehicle is dispatched. Even loading, fixed flow and full-route trips are assumptions. Location, crew and road feasibility remain unverified.</p></section><section class="explain-box"><div class="subheading">EXPLAIN THE ESTIMATE</div><h3>What supports this decision?</h3><div class="explain-options"><button data-question="Why is this section flagged?">Why this section?</button><button data-question="What happens if we add a bus?">What if we add a trip?</button><button data-question="What are the data limitations?">Data limitations</button></div><div id="answer" class="answer">${esc(groundedExplanation(route,state.day,state.hour,state.trips))}</div><form id="askForm" class="ask-form"><input id="question" aria-label="Question about selected route" placeholder="Ask about demand, service or evidence…" maxlength="300"><button type="submit">Ask ↗</button></form></section></div></div></div>`;if(!$('routeDialog').open)$('routeDialog').showModal();showScenario();initMap(route);$('extraTrips').addEventListener('input',showScenario);$('targetLoad').addEventListener('input',showScenario);$('simulateButton').addEventListener('click',async()=>{showScenario();if(state.api)try{await api('/api/scenario',{route_id:id,day_type:state.day,hour:state.hour,trips:state.trips+Number($('extraTrips').value),target_load:Number($('targetLoad').value)})}catch(e){toast(e.message)}toast('Comparison updated. This is a planning scenario, not a dispatch.')});$('askForm').addEventListener('submit',e=>{e.preventDefault();ask($('question').value)})}
function showScenario(){const r=state.data.routes.find(r=>r.id===state.selected);if(!r)return;const extra=Number($('extraTrips').value),target=Number($('targetLoad').value);if(!Number.isInteger(extra)||extra<0||extra>100||!Number.isFinite(target)||target<=0||target>150)return;const before=summary(r),after=plan(flowValues(r,state.day,state.hour),state.trips+extra,target);$('scenarioResult').innerHTML=`<div class="scenario-result"><div><small>BASELINE · ${state.trips} TRIPS/H</small><strong>${before.load===null?'—':before.load.toFixed(1)}</strong><p>${esc(label(before.band))}</p></div><div><small>SCENARIO · ${state.trips+extra} TRIPS/H</small><strong>${after.load===null?'—':after.load.toFixed(1)}</strong><p>${esc(label(after.band))}</p></div></div><p class="muted" style="font-size:11px;margin-bottom:0">Minimum full-route service at this target: <b>${after.needed} trips/hour</b>. Fleet count needs cycle time.</p>`}
function initMap(route){if(!window.L||!route.geometry)return;const el=$('detailMap');el.innerHTML='';state.map=L.map(el,{zoomControl:true,scrollWheelZoom:false});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(state.map);const base=L.geoJSON(route.geometry,{style:{color:'#68717d',weight:5,opacity:.65}}).addTo(state.map);const values=flowValues(route,state.day,state.hour);state.layer=L.featureGroup().addTo(state.map);route.sections.forEach((s,i)=>{if(s.geometry)L.geoJSON(s.geometry,{style:{color:color(state.trips?band(values[i]/state.trips):'no_service'),weight:7,opacity:.95}}).bindPopup(`<b>${esc(s.from_name)} → ${esc(s.to_name)}</b><br>${state.trips?(values[i]/state.trips).toFixed(1):'Undefined'} passengers / bus, planning proxy<br>Map match needs review`).addTo(state.layer)});state.map.fitBounds(base.getBounds(),{padding:[20,20]});setTimeout(()=>state.map?.invalidateSize(),100)}
async function ask(question){const r=state.data.routes.find(r=>r.id===state.selected);if(!r)return;$('answer').textContent='Checking the selected route evidence…';try{if(state.api){const answer=await api('/api/explain',{route_id:r.id,day_type:state.day,hour:state.hour,trips:state.trips,question});$('answer').textContent=answer.answer}else{let answer=groundedExplanation(r,state.day,state.hour,state.trips);if(/add|extra|bus|trip/i.test(question)){const p=summary(r);answer+=`\n\nOne additional trip changes the fixed-flow average to ${(p.peak/(state.trips+1)).toFixed(1)} passengers per bus, assuming even loading.`}$('answer').textContent=answer}}catch(e){$('answer').textContent=e.message}}
function evidence(){const v=state.data.validation;$('evidenceContent').innerHTML=`<p><b>Forecasting and crowding are separate calculations.</b> The current selected forecast is a historical weekday/weekend profile. Service scenarios divide estimated section flow by your assumed trips/hour.</p><p><b>Boarding forecast error:</b> ${(v.boarding_forecast.test.baseline.wape*100).toFixed(2)}% WAPE on March 22–28. This is total absolute passenger error divided by actual target volume, not a classification accuracy.</p><p><b>Section-flow error:</b> ${(v.section_proxy_forecast.test.baseline.wape*100).toFixed(2)}% against reconstructed labels for ten pilot variants. This is not independently measured crowding accuracy.</p><p><b>Destination estimation:</b> ${(v.section_reconstruction.masked_known_destination_validation.top_destination_accuracy*100).toFixed(2)}% exact-destination accuracy on held-out known journeys. Missing destinations are distributed according to training-only known-journey patterns.</p><p><b>Geography:</b> ${state.data.geography.geographic_section_matches} intervals have automatic stop-name/proximity matches. These require operator review. We do not draw invented geographic sections.</p><p><b>Reports:</b> ${state.api?'Saved in a shared SQLite database on the local API server.':'Saved only in this browser in the hosted snapshot. Use the local API deployment for shared driver/manager reports.'}</p><p>These outputs support a prototype planning discussion. They do not establish operational crowding accuracy or physically feasible reroutes.</p>`;$('evidenceDialog').showModal()}
document.addEventListener('click',async e=>{const route=e.target.closest('[data-route]');if(route)openRoute(route.dataset.route);const close=e.target.closest('[data-close]');if(close)$(close.dataset.close).close();const q=e.target.closest('[data-question]');if(q)ask(q.dataset.question);const stage=e.target.closest('[data-section]');if(stage&&state.map){const r=state.data.routes.find(r=>r.id===state.selected),s=r.sections[Number(stage.dataset.section)];if(s.geometry)state.map.fitBounds(L.geoJSON(s.geometry).getBounds(),{padding:[40,40],maxZoom:15});else toast('This interval has no geographic match. Its estimate is shown in the stage list.')}const status=e.target.closest('[data-status]');if(status){if(state.api)await api('/api/incidents/status',{id:status.dataset.id,status:status.dataset.status});else{const item=state.incidents.find(i=>i.id===status.dataset.id);if(item)item.status=status.dataset.status;localStorage.setItem('marina-incidents',JSON.stringify(state.incidents))}loadIncidents()}});
for(const id of['routeDialog','evidenceDialog','guideDialog'])$(id).addEventListener('click',e=>{if(e.target===$(id))$(id).close()});
$('hour').innerHTML=Array.from({length:24},(_,h)=>`<option value="${h}" ${h===18?'selected':''}>${String(h).padStart(2,'0')}:00–${String((h+1)%24).padStart(2,'0')}:00</option>`).join('');
$('dayType').addEventListener('change',e=>{state.day=e.target.value;render()});$('hour').addEventListener('change',e=>{state.hour=Number(e.target.value);render()});$('trips').addEventListener('input',e=>{const n=Number(e.target.value);if(Number.isInteger(n)&&n>=0&&n<=100){state.trips=n;render()}});$('search').addEventListener('input',e=>{state.search=e.target.value;render()});$('networkTab').onclick=()=>switchView(false);$('recommendTab').onclick=()=>switchView(true);function switchView(recs){$('networkView').hidden=recs;$('recommendView').hidden=!recs;$('networkTab').classList.toggle('active',!recs);$('recommendTab').classList.toggle('active',recs);$('pageTitle').innerHTML=recs?'A practical response<span class="title-dot">.</span>':'MTC bus network<span class="title-dot">.</span>'}$('evidenceButton').onclick=evidence;$('mapGuideButton').onclick=()=>$('guideDialog').showModal();
try{try{const health=await api('/api/health');state.api=health.mode==='local_api';if(!state.api)throw Error();state.data=await api('/api/snapshot')}catch{state.data=await(await fetch('./data/snapshot.json')).json()}$('connectionState').textContent=state.api?'LOCAL API CONNECTED · DATA THROUGH 31 MAR':'MODEL SNAPSHOT · DATA THROUGH 31 MAR';$('routeFilters').innerHTML=['all',...new Set(state.data.routes.map(r=>r.route_code))].map(c=>`<button data-filter="${c}" class="${c==='all'?'selected':''}">${c==='all'?'All pilot routes':esc(c)}</button>`).join('');$('routeFilters').onclick=e=>{const b=e.target.closest('[data-filter]');if(b){state.filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render()}};render();await loadIncidents();if(state.api)setInterval(loadIncidents,30000)}catch(e){$('routeGrid').innerHTML=`<div class="empty">Forecast data could not be loaded. ${esc(e.message)}</div>`;$('connectionState').textContent='DATA UNAVAILABLE'}
